using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "NodeViewData", menuName = "Data/Map/NodeViewData")]
public class NodeViewData : ButtonDescriptionData
{
	[Header("Node View Data")]
	public Sprite Icon;

	[SerializeField]
	private bool isBoss;

	[ShowIf("isBoss")]
	public CorruptedAnimalData BossData;

	[Header("SFX")]
	[SerializeField]
	private bool enableOnNodePressedSFX;

	[SerializeField]
	[ShowIf("enableOnNodePressedSFX")]
	private FMODEventReferenceReference onNodePressedSFX;

	public void PlayOnNodePressedSFX()
	{
		if (enableOnNodePressedSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(onNodePressedSFX.Value);
		}
	}
}
